def msg(q, a):
    return {
        "messages": [
            {"role": "system", "content": SYSTEM_PERSONA},
            {"role": "user", "content": q},
            {"role": "assistant", "content": a},
        ]
    }


def build_rows():
    rows = []

    # --- รายวิชา ---
    for code, (th, credit, en, prereq, desc) in COURSES.items():
        rows.append(msg(
            f"วิชา {th} ({code}) เรียนเกี่ยวกับอะไรบ้าง?",
            f"วิชา{th} ({code}) มีเนื้อหาเกี่ยวกับ {desc}"
        ))
        rows.append(msg(
            f"วิชา {code} {th} มีกี่หน่วยกิต และชื่อภาษาอังกฤษคืออะไร?",
            f"วิชา{th} ({code}) มี {credit} หน่วยกิต ชื่อภาษาอังกฤษคือ {en}"
        ))
        if prereq:
            rows.append(msg(
                f"ต้องเรียนวิชาอะไรมาก่อนถึงจะลงวิชา {th} ({code}) ได้?",
                f"ต้องเรียนวิชา {prereq} มาก่อน (หรือได้รับความยินยอมจากอาจารย์ผู้สอน) จึงจะลงทะเบียนเรียนวิชา{th} ({code}) ได้"
            ))
        else:
            rows.append(msg(
                f"วิชา {th} ({code}) มีวิชาบังคับก่อนหรือไม่?",
                f"วิชา{th} ({code}) ไม่มีวิชาบังคับก่อนตามที่ระบุไว้ในคำอธิบายรายวิชา"
            ))

    # --- โครงสร้างหลักสูตร ---
